import {
  integer,
  primaryKey,
  sqliteTable,
  text,
  unique,
} from 'drizzle-orm/sqlite-core';
import type {
  ProfileObservation,
  ProfileReferenceInput,
  ProfileRuntime,
  ProfileProvider,
} from '../../types/design-profile';
import type { GuidanceVerifier } from '../../types/guidance-verifier';
import type { GuidanceAttachment } from '../../types/guidance';
import type { GuidanceReference } from '../../types/guidance-references';
import type { z } from 'zod';
import type {
  GuidanceOriginSchema,
  GuidanceSyncStatus,
} from '../../types/guidance-source';
import type { FailureReasonCode } from '../../utils/failureReason';
import type { SourceSyncMode } from '../../types/source-sync';

export const profile = sqliteTable('profile', {
  singleton: integer().primaryKey(),
  id: text().notNull().unique(),
  isEnabled: integer('is_enabled', { mode: 'boolean' }).notNull(),
  revision: integer().notNull(),
  autonomousReferences: integer('autonomous_references', {
    mode: 'boolean',
  })
    .notNull()
    .default(false),
});
export const guidance = sqliteTable('guidance', {
  id: text().primaryKey(),
  title: text().notNull(),
  markdown: text().notNull(),
  attachments: text({ mode: 'json' }).$type<GuidanceAttachment[]>(),
  references: text({ mode: 'json' }).$type<GuidanceReference[]>(),
  verifier: text({ mode: 'json' }).$type<GuidanceVerifier>(),
  isEnabled: integer('is_enabled', { mode: 'boolean' }).notNull(),
});
export const guidanceSources = sqliteTable('guidance_sources', {
  id: text()
    .primaryKey()
    .references(() => guidance.id, { onDelete: 'cascade' }),
  origin: text({ mode: 'json' })
    .$type<z.infer<typeof GuidanceOriginSchema>>()
    .notNull(),
  sync: text({ mode: 'json' }).$type<GuidanceSyncStatus>().notNull(),
  syncMode: text('sync_mode')
    .$type<SourceSyncMode>()
    .notNull()
    .default('daily'),
});
export const indexRebuild = sqliteTable('index_rebuild', {
  singleton: integer().primaryKey(),
  id: text().notNull(),
  runtime: text().$type<ProfileRuntime>().notNull(),
});
export const providerCooldowns = sqliteTable('provider_cooldowns', {
  provider: text().$type<ProfileProvider>().primaryKey(),
  retryAt: text('retry_at').notNull(),
  attempts: integer().notNull(),
});
export const sources = sqliteTable(
  'sources',
  {
    id: text().primaryKey(),
    provider: text().$type<ProfileProvider>().notNull(),
    remoteId: text('remote_id').notNull(),
    resolvedRemoteId: text('resolved_remote_id'),
    title: text().notNull(),
    url: text(),
    isIncluded: integer('is_included', { mode: 'boolean' }).notNull(),
    removedAt: text('removed_at'),
    syncMode: text('sync_mode')
      .$type<SourceSyncMode>()
      .notNull()
      .default('daily'),
  },
  (table) => [unique().on(table.provider, table.remoteId)],
);
export const references = sqliteTable('profile_references', {
  id: text().primaryKey(),
  revision: integer().notNull(),
  contentHash: text('content_hash').notNull(),
  body: text({ mode: 'json' }).$type<ProfileReferenceInput>().notNull(),
});
export const memberships = sqliteTable(
  'memberships',
  {
    sourceId: text('source_id')
      .notNull()
      .references(() => sources.id),
    referenceId: text('reference_id')
      .notNull()
      .references(() => references.id),
    seenJobId: text('seen_job_id'),
  },
  (table) => [primaryKey({ columns: [table.sourceId, table.referenceId] })],
);
export const importCollectionReferences = sqliteTable(
  'import_collection_references',
  {
    jobId: text('job_id')
      .notNull()
      .references(() => importJobs.id),
    collectionId: text('collection_id').notNull(),
    referenceId: text('reference_id')
      .notNull()
      .references(() => references.id),
  },
  (table) => [
    primaryKey({
      columns: [table.jobId, table.collectionId, table.referenceId],
    }),
  ],
);
export const observations = sqliteTable('observations', {
  referenceId: text('reference_id')
    .primaryKey()
    .references(() => references.id),
  revision: integer().notNull(),
  body: text({ mode: 'json' }).$type<ProfileObservation>().notNull(),
});
export const indexWork = sqliteTable('index_work', {
  referenceId: text('reference_id')
    .primaryKey()
    .references(() => references.id),
  id: text().notNull(),
  revision: integer().notNull(),
  operation: text({ enum: ['upsert', 'delete'] }).notNull(),
  engineId: text('engine_id'),
  state: text({ enum: ['pending', 'indexed'] }).notNull(),
});
export const importJobs = sqliteTable('import_jobs', {
  isEnumerated: integer('is_enumerated', { mode: 'boolean' })
    .notNull()
    .default(false),
  id: text().primaryKey(),
  sourceId: text('source_id')
    .notNull()
    .references(() => sources.id),
  runtime: text().$type<ProfileRuntime>().notNull(),
  state: text({
    enum: ['pending', 'paused', 'complete', 'failed', 'superseded'],
  }).notNull(),
  cursor: text(),
  enumerated: integer().notNull(),
  total: integer(),
  error: text(),
  updatedAt: text('updated_at').notNull(),
  addedCount: integer('added_count').notNull().default(0),
  removedCount: integer('removed_count').notNull().default(0),
});

export const importCursors = sqliteTable(
  'import_cursors',
  {
    jobId: text('job_id')
      .notNull()
      .references(() => importJobs.id),
    cursor: text().notNull(),
  },
  (table) => [primaryKey({ columns: [table.jobId, table.cursor] })],
);

export const referenceFailures = sqliteTable(
  'reference_failures',
  {
    jobId: text('job_id')
      .notNull()
      .references(() => importJobs.id),
    referenceId: text('reference_id')
      .notNull()
      .references(() => references.id),
    revision: integer().notNull(),
    stage: text({ enum: ['download', 'analysis'] }).notNull(),
    error: text().notNull(),
    reasonCode: text('reason_code').$type<FailureReasonCode>(),
    attempts: integer().notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.jobId, table.referenceId, table.stage] }),
  ],
);
